package net.civeira.phylax.feature.observe.observedissuealias.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class OriginVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property origin of observed issue alias ")
  void test_origin_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", OriginVO.fromReference("10").getOriginUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", OriginVO.tryFromReference("11").getOriginUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", OriginVO.tryFromReference("12", fails).getOriginUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> OriginVO.tryFrom(null));
    Assertions.assertEquals(ObservedSourceReference.of("one"),
        OriginVO.from(ObservedSourceReference.of("one")).getOrigin());
    Assertions.assertThrows(ConstraintException.class, () -> OriginVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + ObservedSourceReference.of("one") + "]",
        OriginVO.from(ObservedSourceReference.of("one")).toString());
  }
}
